command:
let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled?.find(t => t.actor?.getFlag("vagabond-app", "tap"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "tap")) return;

const name = hero.system.parent.name;
let tap = hero.effects.find(fx => fx.name.toUpperCase() === "TAP");

// Add 'Tap' Active Effect if they don't yet have it...
if (!tap) {
  const effectData = {
    name: "Tap",
    img: "icons/magic/symbols/circle-ouroboros.webp",
    diabled: false,
    showIcon: 2,
    changes: [
      {
        key: "system.health.max",
        mode: 2,
        value: "0",
        priority: 20
      }
    ]
  }
  await token.actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
  tap = hero.effects.find(fx => fx.name.toUpperCase() === "TAP");
}

// Current Tap HP value...
const tapHp = (hero.effects.find(fx => fx.name.toUpperCase() ==="TAP").changes[0]?.value || 0) - 1;

// Exchange HP for Mana, 1:1...
if (hero.system.health.max > 0) {

  // Update the Tap ActiveEffect document
  await tap.update({
    "disabled": false,
    "changes": [{
      "key": "system.health.max",
      "mode": 2,
      "value": tapHp,
      "priority": 20
    }]
  });

  if (hero.system.health.value > hero.system.health.max) {
    await hero.update({ "system.health.value": hero.system.health.max });
  }

  // Add 1 Mana
  await hero.update({ "system.mana.value": hero.system.mana.value + 1 });

  // Notify chat...
  ChatMessage.create({
    user: game.user._id,
    speaker: ChatMessage.getSpeaker({ token: hero }),
    content: hero.system.health.max > 0
      ? `${name}: Tapping HP for Mana.<br>Max HP reduced to: ${hero.system.health.max}`
      : `${name} has been vaporized by their own <i>magnificense</i>. The spell will now resolve...`
  })
}
